<template><main class="overlay-manager"><header class="overlay-manager__hero"><div><p class="overlay-kicker">Universal Widget Overlays</p><h1>My Overlays</h1><p>Build multi-provider stream layouts in one canvas. This phase is a browser-local simulation.</p><div class="local-demo-status"><b>Local Demo</b><span>{{ overlayState.saveLabel }}</span></div></div><button type="button" class="primary-action" @click="create">+ Create overlay</button></header><p v-if="overlayState.recoveredStorage" class="recovery-notice" role="status">Invalid or older demo storage was safely replaced with starter layouts.</p><section class="overlay-grid" aria-label="Saved demo overlays"><article v-for="overlay in overlayState.overlays" :key="overlay.id" class="overlay-card"><div class="overlay-card__preview"><div v-for="widget in overlay.widgets.slice(0,5)" :key="widget.id" :style="miniFrame(widget,overlay)"></div><span>LOCAL DEMO</span></div><div class="overlay-card__body"><input v-if="renaming===overlay.id" ref="renameInput" :value="overlay.name" aria-label="Overlay name" @keyup.enter="finishRename(overlay,$event)" @blur="finishRename(overlay,$event)"><h2 v-else>{{ overlay.name }}</h2><p>{{ overlay.resolution.width }} × {{ overlay.resolution.height }} · {{ overlay.widgets.length }} widgets</p><small>Last edited {{ formatDate(overlay.updatedAt) }}</small><div class="overlay-card__actions"><RouterLink :to="{name:'CreatorOverlayEditor',params:{overlayId:overlay.id}}">Edit</RouterLink><RouterLink :to="{name:'CreatorOverlayEditor',params:{overlayId:overlay.id},query:{mode:'preview'}}">Preview</RouterLink><button type="button" @click="renaming=overlay.id">Rename</button><button type="button" @click="duplicateOverlay(overlay.id)">Duplicate</button><button type="button" class="danger" :disabled="overlayState.overlays.length<=1" @click="remove(overlay)">Delete</button></div></div></article></section><OverlayBrowserSourceCard :resolution="{width:1920,height:1080}"/></main></template>
<script setup>import { nextTick,ref } from 'vue'; import { useRouter } from 'vue-router'; import OverlayBrowserSourceCard from '../../components/overlays/OverlayBrowserSourceCard.vue'; import { addOverlay,deleteOverlay,duplicateOverlay,overlayState,renameOverlay } from '../../overlays/overlayStore.js'; const router=useRouter();const renaming=ref('');const renameInput=ref(null);function create(){const overlay=addOverlay(`Overlay ${overlayState.overlays.length+1}`);router.push({name:'CreatorOverlayEditor',params:{overlayId:overlay.id}})}function finishRename(overlay,event){renameOverlay(overlay.id,event.target.value);renaming.value=''}function remove(overlay){if(window.confirm(`Delete “${overlay.name}” from this browser?`))deleteOverlay(overlay.id)}function miniFrame(widget,overlay){return{left:`${widget.frame.x/overlay.resolution.width*100}%`,top:`${widget.frame.y/overlay.resolution.height*100}%`,width:`${widget.frame.width/overlay.resolution.width*100}%`,height:`${widget.frame.height/overlay.resolution.height*100}%`,zIndex:widget.zIndex}}function formatDate(value){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}async function startRename(id){renaming.value=id;await nextTick();renameInput.value?.focus()}</script>
<style scoped src="./overlays.css"></style>
